     * （对应开发文档 10.2 场景⑧：进程被杀）。返回改标数量。
     */
    fun `recoverOrphanedSessions`(): kotlin.Long
    
    /**
     * 草稿恢复对话框的三个操作分支（开发文档 10.4）。
     */
    fun `resumeOrFinalize`(`sessionId`: kotlin.Long, `action`: SessionResumeAction): ImageInfo?
    
    /**
     * 通用状态迁移（仅允许开发文档 10.1 定义的合法路径）。
     */
    fun `transitionStatus`(`sessionId`: kotlin.Long, `target`: SessionStatus, `reason`: kotlin.String?): SessionInfo
    
    companion object
}

