/**
 * 会话执行器：持有内存中的已拼接长图，负责逐帧拼接与检查点落盘。
 */
public interface SessionRunnerInterface {
    
    /**
     * 模式①②：通过重叠匹配自动定位偏移并拼接。
     */
    fun `appendFrameDetected`(`framePng`: kotlin.ByteArray, `minOverlap`: kotlin.UInt, `maxOverlap`: kotlin.UInt): SessionProgress
    
    /**
     * 模式③④：按已知固定偏移直接裁剪拼接，不做重叠置信度判断。
     */
    fun `appendFrameFixed`(`framePng`: kotlin.ByteArray, `expectedOffset`: kotlin.UInt): SessionProgress
    
    /**
     * 正常完成：生成最终长图写入项目并清理草稿（场景① / ⑩）。
     */
    fun `complete`(): ImageInfo?
    
    /**
     * 丢弃：删除检查点草稿并置为已丢弃（场景② / ⑪）。
     */
    fun `discard`()
    
    /**
     * 硬中断（无障碍关闭 / 权限撤销 / 存储异常 / 进程被杀），对应场景⑥⑦⑨。
     */
    fun `interrupt`(`reason`: kotlin.String): SessionInfo
    
    /**
     * 软暂停（切后台 / 锁屏 / 系统弹窗打断），对应场景③④⑤。
     */
    fun `pause`(`reason`: kotlin.String?): SessionInfo
    
    /**
     * 当前进度（供 Kotlin 侧展示帧数 / 尺寸 / 完成判定）。
     */
    fun `progress`(): SessionProgress
    
    /**
     * 从硬中断/软暂停中以当前草稿内容保存为已完成图片（与 SaveAsIs 等价）。
     */
    fun `saveAsIs`(): ImageInfo?
    
    companion object
}

