    @Throws(CoreException::class)override fun `createProject`(`prefix`: kotlin.String, `displayName`: kotlin.String): ProjectInfo {
            return FfiConverterTypeProjectInfo.lift(
    callWithHandle {
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_hyperss_core_fn_method_storage_create_project(
        it,
        
        FfiConverterString.lower(`prefix`),
        FfiConverterString.lower(`displayName`),_status)
}
    }
    )
