/**
 * 业务错误统一枚举，通过 UniFFI 映射为 Kotlin 侧的异常类。
 * 所有字段限定为 String / 基本类型，保证跨 FFI 边界的可转换性。
 */
sealed class CoreException: kotlin.Exception() {
    
    class Database(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Io(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Image(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Config(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidPrefix(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class ProjectNotFound(
        
        val `id`: kotlin.Long
        ) : CoreException() {
        override val message
            get() = "id=${ `id` }"
    }
    
    class PrefixExists(
        
        val `prefix`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "prefix=${ `prefix` }"
    }
    
    class ImageNotFound(
        
        val `id`: kotlin.Long
        ) : CoreException() {
        override val message
            get() = "id=${ `id` }"
    }
    
    class SessionNotFound(
        
        val `id`: kotlin.Long
        ) : CoreException() {
        override val message
            get() = "id=${ `id` }"
    }
    
    class SequenceExhausted(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class InvalidTransition(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class StitchLowConfidence(
        
        val `confidence`: kotlin.Float
        ) : CoreException() {
        override val message
            get() = "confidence=${ `confidence` }"
    }
    
    class NoDraft(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class WidthMismatch(
        
        val `a`: kotlin.UInt, 
        
        val `b`: kotlin.UInt
        ) : CoreException() {
        override val message
            get() = "a=${ `a` }, b=${ `b` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Database(
                FfiConverterString.read(buf),
                )
            2 -> CoreException.Io(
                FfiConverterString.read(buf),
                )
            3 -> CoreException.Image(
                FfiConverterString.read(buf),
                )
            4 -> CoreException.Config(
                FfiConverterString.read(buf),
                )
            5 -> CoreException.InvalidPrefix(
                FfiConverterString.read(buf),
                )
            6 -> CoreException.ProjectNotFound(
                FfiConverterLong.read(buf),
                )
            7 -> CoreException.PrefixExists(
                FfiConverterString.read(buf),
                )
            8 -> CoreException.ImageNotFound(
                FfiConverterLong.read(buf),
                )
            9 -> CoreException.SessionNotFound(
                FfiConverterLong.read(buf),
                )
            10 -> CoreException.SequenceExhausted()
            11 -> CoreException.InvalidTransition(
                FfiConverterString.read(buf),
                )
            12 -> CoreException.StitchLowConfidence(
                FfiConverterFloat.read(buf),
                )
            13 -> CoreException.NoDraft()
            14 -> CoreException.WidthMismatch(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Database -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Image -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Config -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.InvalidPrefix -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.ProjectNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`id`)
            )
            is CoreException.PrefixExists -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`prefix`)
            )
            is CoreException.ImageNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`id`)
            )
            is CoreException.SessionNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`id`)
            )
            is CoreException.SequenceExhausted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.InvalidTransition -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.StitchLowConfidence -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterFloat.allocationSize(value.`confidence`)
            )
            is CoreException.NoDraft -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.WidthMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`a`)
                + FfiConverterUInt.allocationSize(value.`b`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Database -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Io -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Image -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Config -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.InvalidPrefix -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.ProjectNotFound -> {
                buf.putInt(6)
                FfiConverterLong.write(value.`id`, buf)
                Unit
            }
            is CoreException.PrefixExists -> {
                buf.putInt(7)
                FfiConverterString.write(value.`prefix`, buf)
                Unit
            }
            is CoreException.ImageNotFound -> {
                buf.putInt(8)
                FfiConverterLong.write(value.`id`, buf)
                Unit
            }
            is CoreException.SessionNotFound -> {
                buf.putInt(9)
                FfiConverterLong.write(value.`id`, buf)
                Unit
            }
            is CoreException.SequenceExhausted -> {
                buf.putInt(10)
                Unit
            }
            is CoreException.InvalidTransition -> {
                buf.putInt(11)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.StitchLowConfidence -> {
                buf.putInt(12)
                FfiConverterFloat.write(value.`confidence`, buf)
                Unit
            }
            is CoreException.NoDraft -> {
                buf.putInt(13)
                Unit
            }
            is CoreException.WidthMismatch -> {
                buf.putInt(14)
                FfiConverterUInt.write(value.`a`, buf)
                FfiConverterUInt.write(value.`b`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



